public class CauseChain {
    public static void main(String[] args) {
        try {
            level1();
        } catch (RuntimeException e) {
            System.out.println(e.getMessage());
            System.out.println(e.getCause().getMessage());
            System.out.println(e.getCause().getCause().getMessage());
        }
    }

    static void level1() {
        try {
            level2();
        } catch (RuntimeException e) {
            throw new RuntimeException("L1", e);
        }
    }

    static void level2() {
        try {
            level3();
        } catch (RuntimeException e) {
            throw new RuntimeException("L2", e);
        }
    }

    static void level3() {
        throw new RuntimeException("L3");
    }
}

public class InitCauseTest {
    public static void main(String[] args) {
        RuntimeException original = new RuntimeException("original");
        RuntimeException wrapper = new RuntimeException("wrapper", original);
        try {
            wrapper.initCause(new RuntimeException("another"));
        } catch (Exception e) {
            System.out.println(e.getClass().getSimpleName());
        }
    }
}
